def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                rr, cc = stack.pop()
                cells.append((rr, cc))
                for nr, nc in ((rr - 1, cc), (rr + 1, cc),
                               (rr, cc - 1), (rr, cc + 1)):
                    if (0 <= nr < h and 0 <= nc < w
                            and (nr, nc) not in seen
                            and grid[nr][nc] == color):
                        seen.add((nr, nc))
                        stack.append((nr, nc))
            components.append((color, cells))

    frames = []
    for i, (color, cells) in enumerate(components):
        rmin = min(r for r, c in cells)
        rmax = max(r for r, c in cells)
        cmin = min(c for r, c in cells)
        cmax = max(c for r, c in cells)
        if rmax - rmin < 2 or cmax - cmin < 2:
            continue

        border = set()
        for c in range(cmin, cmax + 1):
            border.add((rmin, c))
            border.add((rmax, c))
        for r in range(rmin, rmax + 1):
            border.add((r, cmin))
            border.add((r, cmax))

        if set(cells) == border:
            frames.append((i, color, rmin, rmax, cmin, cmax, cells))

    frame_ids = {frame[0] for frame in frames}
    output = [[bg for _ in range(w)] for _ in range(h)]

    for _, color, _, _, _, _, cells in frames:
        for r, c in cells:
            output[r][c] = color

    for _, color, rmin, rmax, cmin, cmax, _ in frames:
        count = sum(
            1 for i, (other_color, _) in enumerate(components)
            if i not in frame_ids and other_color == color
        )
        middle_row = (rmin + rmax) // 2
        for k in range(1, count + 1):
            c = cmax - 2 * k
            if cmin < c < cmax:
                output[middle_row][c] = color

    return output
